{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "All observational studies (eg, cross-sectional, cohort, case-control studies, and case series) except for case reports were included. We included studies that reported the prevalence of COVID-19 in HCWs, using either reverse transcription-polymerase chain reaction (RT-PCR) or a serum antibodies assay. We also included studies evaluating the risk factors for SARS-CoV-2 infection and those analyzing the clinical characteristics and outcomes of laboratory-confirmed COVID-19 among HCWs. We excluded those articles that evaluated HCWs with suspected but not laboratory-confirmed SARS-CoV-2 infection.",
      "reason": "The text explicitly specifies eligible study designs (observational, cross-sectional, etc.), population (HCWs), outcomes (prevalence, risk factors, clinical characteristics), and exclusion criteria (case reports, suspected not confirmed)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Medline, Embase, Latin American and Caribbean Health Sciences Literature (LILACS), Cochrane, Web of Science, the World Health Organization COVID-19 database, Google Scholar, and Living Evidence on COVID-19, a database developed by the Institute of Social and Preventive Medicine, University of Bern, were searched to identify relevant articles from inception until July 8, 2020, without language restrictions.",
      "reason": "The text specifies the time frame (inception until July 8, 2020) and language restrictions (without language restrictions), which are report characteristics."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided text does not distinguish between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported. It focuses on population eligibility (suspected vs confirmed)."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "On the basis of the data from each study (extracted by 2 independent investigators), we first estimated the global prevalence of SARS-CoV-2 infection by each test used for screening (RT-PCR vs. antibodies tests). ... Screening criteria, geographic location, HCW professions, the clinical setting, and the mean of daily new cases of SARS-CoV-2 per million inhabitants (15) in the country during the period in which the study was carried out were prespecified as characteristics for assessment of heterogeneity and were evaluated using stratified analyses and univariate random-effects meta-regression.",
      "reason": "The text specifies how studies were grouped for synthesis (by test type, geographic location, HCW professions, clinical setting) and links these to the analysis methods."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "While eligibility criteria are listed, the text does not provide explicit rationales for notable restrictions (e.g., why exclude case reports, why limit to 2020, why exclude suspected cases)."
    }
  ],
  "confidence": 90
}

